72: {
73:     // Reset color
74:     Reset = 0,
75:     
76:     // Standard ANSI colors (30-37, 40-47)
77:     Black,
78:     Red, 
79:     Green,
80:     Yellow,
81:     Blue,
82:     Magenta,
83:     Cyan,
84:     Gray,
85:     
86:     // Bright ANSI colors (90-97, 100-107)
87:     DarkGray,
88:     LightRed,
89:     LightGreen,
90:     LightYellow,
91:     LightBlue,
92:     LightMagenta,
93:     LightCyan,
94:     White,
95:     
96:     // Extended color modes
97:     Rgb,     // 24-bit true color
98:     Indexed  // 8-bit 256 color
99: }
100: 
101: public readonly struct Color : IEquatable<Color>
102: {
103:     public ColorType Type { get; }
104:     public byte R { get; }      // RGB red component or indexed value
105:     public byte G { get; }      // RGB green component 
106:     public byte B { get; }      // RGB blue component
107:     
108:     // Factory methods for different color types
109:     public static Color Reset => new(ColorType.Reset);
110:     public static Color Black => new(ColorType.Black);
111:     public static Color Red => new(ColorType.Red);
112:     // ... other ANSI colors
113:     
114:     public static Color Rgb(byte r, byte g, byte b) => new(ColorType.Rgb, r, g, b);
115:     public static Color Indexed(byte index) => new(ColorType.Indexed, index, 0, 0);
116:     public static Color FromU32(uint value) => Rgb((byte)(value >> 16), (byte)(value >> 8), (byte)value);
117:     
118:     // String parsing with comprehensive format support
119:     public static Color Parse(string colorString);
120:     public static bool TryParse(string colorString, out Color color);
